1065	function sanitizePillarResult(
1066	  raw: Record<string, unknown> | undefined,
1067	  prefix: string,
1068	): { score: number; findings: Finding[] } {
1069	  if (!raw || typeof raw !== "object") {
1070	    return { score: 50, findings: [] };
1071	  }
1072	
1073	  const score = typeof raw.score === "number"
1074	    ? Math.max(0, Math.min(100, Math.round(raw.score)))
1075	    : 50;
1076	
1077	  const rawFindings = Array.isArray(raw.findings) ? raw.findings : [];
1078	  const findings: Finding[] = rawFindings
1079	    .filter((f): f is Record<string, unknown> => f !== null && typeof f === "object")
1080	    .map((f, i) =>
1081	      sanitizeFinding(f, `f_${prefix}_${String(i + 1).padStart(2, "0")}`)
1082	    );
1083	
1084	  return { score, findings };
1085	}
