1097	function buildDefaultTextResult(): TextAnalysisResult {
1098	  const defaultPillar = { score: 50, findings: [] };
1099	  return {
1100	    value_proposition: defaultPillar,
1101	    content_copy: defaultPillar,
1102	  };
1103	}
