289	    const { error: updateError } = await supabase
290	      .from("scans")
291	      .update({
292	        status: "completed",
293	        overall_score: scoring.overall_score,
294	        issues_found: scoring.issues_found,
295	        critical_issues: scoring.critical_issues,
296	        warnings: scoring.warnings,
297	        quick_wins: scoring.quick_wins,
298	        completed_at: new Date().toISOString(),
299	      })
300	      .eq("id", scanId);
301	
302	    if (updateError) {
303	      console.error("Failed to update scan status:", updateError);
304	      // Results are saved — don't fail the whole scan
305	    }
306	
307	    // ── 11. Send scan complete email (fire-and-forget) ─────────────
308	    try {
309	      // Fetch user profile for name and email
310	      const [profileRes, emailRes] = await Promise.all([
311	        supabase
312	          .from("profiles")
313	          .select("full_name, company_name")
314	          .eq("id", user.id)
315	          .single(),
316	        supabase.auth.admin.getUserById(user.id),
317	      ]);
318	
319	      const userName = profileRes.data?.full_name ?? "there";
320	      const userEmail = emailRes.data?.user?.email;
321	
322	      if (userEmail) {
323	        await supabase.functions.invoke("send-email", {
324	          body: {
325	            type: "scan_complete",
326	            to: userEmail,
327	            data: {
328	              name: userName,
329	              url,
330	              score: scoring.overall_score,
331	              scan_id: scanId,
332	              critical_count: scoring.critical_issues,
333	              quick_wins: scoring.quick_wins,
334	            },
335	          },
336	        });
337	      }
338	    } catch (emailErr) {
339	      // Non-critical: never fail a scan because the notification email failed
340	      console.warn("Scan complete email failed (non-fatal):", emailErr);
341	    }
342	
343	    return corsResponse({ scan_id: scanId, overall_score: scoring.overall_score });
344	  } catch (error) {
345	    const msg = error instanceof Error ? error.message : "Unexpected error during scan";
346	    console.error("Unexpected scan error:", error);
347	    await failScan(msg);
348	    return corsResponse({ error: "Scan failed due to an unexpected error" }, 500);
349	  }

